mapper.update:

UPDATE db_contract_plan SET status = N'APPROVED', approved_by = #{approvedBy},
       approved_at = SYSUTCDATETIME(), approval_note = #{note}, updated_at = SYSUTCDATETIME()
WHERE id = #{id} AND status = N'DRAFT' AND row_version = #{version}


UPDATE db_contract_plan SET status = N'EXECUTING', executed_by = #{executedBy},
       executed_at = SYSUTCDATETIME(), failure_message = NULL, updated_at = SYSUTCDATETIME()
WHERE id = #{id} AND status = N'APPROVED' AND row_version = #{version}


UPDATE db_contract_plan SET status = N'FAILED', failure_message = #{message},
       executed_at = SYSUTCDATETIME(), updated_at = SYSUTCDATETIME()
WHERE id = #{id} AND status = N'APPROVED' AND row_version = #{version}
